from marshmallow import Schema, fields, EXCLUDE
import pytest

EXPECTED_SYMPTOM = {
    "exception_type": "AttributeError",
    "message_regex": "'NoneType' object has no attribute",
    "description": "Nested schema load raises AttributeError on None object with EXCLUDE",
    "target_symbols": ["marshmallow.schema.Schema._invoke_field_validators"],
}

class Child(Schema):
    name = fields.Str()

class Parent(Schema):
    child = fields.Nested(Child, unknown=EXCLUDE)

def test_reproduce_issue():
    schema = Parent()
    schema.load({'child': None})
